"""Option tactician for the portable CPU player (generated by gen_portable_opt.py -- do not edit by hand).

What it is: every 20 physics ticks (3 Hz) the 27 legal features (+ their EMA) go through a tiny head (ridge or 2x64 MLP ensemble,
numpy) that predicts, for each of 7 tactics, the judge-score gain of flying that tactic for 2 s and then PURSUE.  If the enemy is
closer than 3.5 km and the best predicted gain is > tau, that tactic is COMMITTED for 6 decisions; otherwise PURSUE (the base pilot's
own law).  The heads were trained offline on counterfactual rollouts of the local simulator (README 6.8 - 6.14).

Only local-harness evidence exists; NOT Host-validated.  Uses: numpy, combat_v3.*, and fighter.py (the user's portable file).
"""
import base64, io, json, math
import numpy as np
import fighter as F
from fighter import validate_observation, geometry_from_observation

FEAT_DIM = 27


def _wrap(a):
    return (a + 180.) % 360. - 180.


def features(o, atk_ticks, tick):
    g = geometry_from_observation(o)
    phi, theta = math.radians(o[3]), math.radians(o[4])
    ev, ov = o[23:26], o[6:9]
    cross = _wrap(math.degrees(math.atan2(ev[1], ev[0])) - math.degrees(math.atan2(ov[1], ov[0]))) / 180.
    d_ft = g['distance_m'] / .3048
    in_band = 500. <= d_ft <= 3000.
    ba = g['blue_angle_deg']
    c = np.clip
    f = [min(g['distance_m'] / 5000., 3.), c(g['closing_mps'] / 340., -3, 3), ba / 180., g['blue_az_deg'] / 180.,
         g['blue_el_deg'] / 90., g['aspect_proxy_deg'] / 180., cross,
         math.sin(phi), math.cos(phi), math.sin(theta), math.cos(theta),
         c(o[18] / 30., -3, 3), c(o[19] / 10., -3, 3), c(o[14] / 9., -2, 2),
         o[12] / 1.6878098571011957 / 400., o[2] * .3048 / 6000.,
         c((o[22] - o[2]) * .3048 / 3000., -3, 3), float(np.linalg.norm(ev)) / 1.6878098571011957 / 400.,
         c(o[8] * .3048 / 100., -3, 3), c(o[9] / 3., -1, 1), c(o[10] / 3., -1, 1), c(o[11] / 3., -1, 1),
         atk_ticks / 180., tick / 18000., float(in_band and ba <= 1.), float(in_band), float(ba <= 5.)]
    return np.asarray(f, dtype=np.float32)

